	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/me/follow-requests/{userId}", wrapper.DeclineFollowRequest)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/me/follow-requests/{userId}", wrapper.AcceptFollowRequest)
